BEGIN;
CREATE TABLE IF NOT EXISTS principals (id text PRIMARY KEY, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS sources (id text PRIMARY KEY, subject_id text NOT NULL REFERENCES principals(id), kind text NOT NULL, external_id text, captured_on date, captured_at timestamptz, time_zone text, original_text text, asset_version_id text, revision integer NOT NULL DEFAULT 1, CONSTRAINT sources_content_required CHECK (original_text IS NOT NULL OR asset_version_id IS NOT NULL), CONSTRAINT sources_capture_time_required CHECK (captured_on IS NOT NULL OR captured_at IS NOT NULL));
CREATE UNIQUE INDEX IF NOT EXISTS sources_subject_external_unique ON sources(subject_id, kind, external_id) WHERE external_id IS NOT NULL;
CREATE TABLE IF NOT EXISTS meals (id text PRIMARY KEY, subject_id text NOT NULL REFERENCES principals(id), occurred_on date NOT NULL, occurred_at timestamptz, time_zone text NOT NULL, meal_type text NOT NULL, note text, revision integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS meals_subject_date_idx ON meals(subject_id, occurred_on);
CREATE TABLE IF NOT EXISTS intake_items (id text PRIMARY KEY, subject_id text NOT NULL REFERENCES principals(id), meal_id text NOT NULL REFERENCES meals(id) ON DELETE CASCADE, position integer NOT NULL, name text NOT NULL, quantity numeric(24,6), unit text, energy_kcal numeric(24,6), estimate boolean NOT NULL DEFAULT false, evidence_note text, revision integer NOT NULL DEFAULT 1, UNIQUE(meal_id, position), CHECK ((quantity IS NULL) = (unit IS NULL)), CHECK (NOT estimate OR evidence_note IS NOT NULL));
CREATE TABLE IF NOT EXISTS money_entries (id text PRIMARY KEY, subject_id text NOT NULL REFERENCES principals(id), entry_type text NOT NULL, amount numeric(24,6) NOT NULL CHECK (amount > 0), currency text NOT NULL CHECK (currency ~ '^[A-Z]{3}$'), occurred_on date NOT NULL, occurred_at timestamptz, time_zone text NOT NULL, note text, revision integer NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS meal_money_links (meal_id text NOT NULL REFERENCES meals(id) ON DELETE CASCADE, money_entry_id text NOT NULL REFERENCES money_entries(id), PRIMARY KEY(meal_id, money_entry_id));
CREATE TABLE IF NOT EXISTS meal_source_links (meal_id text NOT NULL REFERENCES meals(id) ON DELETE CASCADE, source_id text NOT NULL REFERENCES sources(id), PRIMARY KEY(meal_id, source_id));
CREATE TABLE IF NOT EXISTS operations (execution_id text PRIMARY KEY, subject_id text NOT NULL REFERENCES principals(id), command_id text NOT NULL, capability text NOT NULL, capability_version integer NOT NULL, fingerprint text NOT NULL, result jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(subject_id, command_id));
CREATE TABLE IF NOT EXISTS outbox (id text PRIMARY KEY, subject_id text NOT NULL REFERENCES principals(id), event_type text NOT NULL, aggregate_id text NOT NULL, payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), delivered_at timestamptz);
CREATE INDEX IF NOT EXISTS outbox_pending_idx ON outbox(created_at) WHERE delivered_at IS NULL;
COMMIT;
